SELECT makername, COUNT(*) FROM (
    SELECT di.makername, di.modnum AS model
    FROM deviceidentity di
    JOIN testsessions ts ON di.devsessionref = ts.sessionregistry
    WHERE di.conntype IN ('Wireless 2.4GHz', 'Hybrid', 'Bluetooth')
) sub GROUP BY makername ORDER BY makername;

SELECT COUNT(*) FROM deviceidentity di
JOIN testsessions ts ON di.devsessionref = ts.sessionregistry
WHERE di.conntype IN ('Wireless 2.4GHz', 'Bluetooth');

SELECT COUNT(*) FROM (
    SELECT di.modnum, ROUND(CAST((ts.battlifeh * ts.battcapmah) / (di.pwractmw * 10) AS numeric), 2) AS ber
    FROM deviceidentity di
    JOIN testsessions ts ON di.devsessionref = ts.sessionregistry
    WHERE di.conntype IN ('Wireless 2.4GHz', 'Bluetooth')
) sub WHERE ber > 7.5;

-- Check if performance table has any power-related columns
SELECT * FROM information_schema.columns 
WHERE table_name = 'performance' AND column_name LIKE '%pwr%';
